INSERT INTO issue_refs(global_id, url, temp_id, created_at) VALUES('ref-01M0V940AVPRE48N0S5H08EKTV', 'https://github.com/HiQS-Labs/rebalanceOS/issues/120', NULL, '2026-08-25T01:38:53Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5FS9F0H2EKDTHEPKDE', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.69.0', 'Reclaim', 'shipped', '2026-08-15', '2026-08-14', 'Reclaimed the ~11 GB the vector store had leaked to orphaned embeddings, then re-embedded what was missing. #250 vector bloat — reclaim + backfill + re-embed. Root cause already fixed in PR #249.', NULL, 'ref-01M0V6SS5FVXHZCQJCER3V8TCG', NULL, 'https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/250', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5FEQMK5FVTZHR7KPRR', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.70.0', 'Green Board', 'draft', '2026-09-15', NULL, 'The first release a stranger can clone and succeed with — published to a new public repository under its own organization, with install, onboarding and secret-scanning proven rather than assumed. #66 release-gate tracker (front-door, shakedown, TruffleHog), #67 working-directory-dependent tests. Both carry forward work the retiring repo tracked as #276 and #255; its #275, #273 and #242 were re-verified against this tree on 2026-08-18 and are already fixed here, and #178/#225 are confirmed stale — evidence in #66. 3-Eyes excluded by operator decision as diagnostics rather than core. Scope QA''d by cross-model relay 2026-08-15 (Approved r5), remap QA''d 2026-08-18.', NULL, 'ref-01M0V6SS5FGGBXYFHPA08MMWCH', NULL, 'https://github.com/HiQS-Suite/rebalanceOS/issues/66', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GPFMAANZG4GYFAV4X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.71.0', 'Subtraction', 'draft', '2026-10-15', NULL, 'Deletes rather than adds — removes surfaces, renderers and models the product no longer earns, measured as net negative lines. #271 subtraction pass (C1-C8) — absorbs the open GH-266 Phase 4 remnants (stale MCP docs, weakened assertion, TF-IDF keyset pagination). Run as a marathon; plan and per-lane contracts in PROJECT/2-WORKING/GH-271-SUBTRACTION/.', NULL, 'ref-01M0V6SS5GPZBJE67W056VBQG6', NULL, 'https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/271', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GE588Z6MNRK6X4Y6H', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.72.0', 'Daily Driver', 'draft', '2026-11-15', NULL, 'Proves the product survives a week of real daily use on one machine without intervention; no new features, only evidence. Proof, not new work — consolidates the former 0.71.0 Daily Driver and 0.72.0 Punch List into one milestone. Prerequisites: #216 MLX instrumentation, #217 MLX memory cap. Regression gates only: #209, #210, #213, #215, #222 (closed).', NULL, 'ref-01M0V6SS5GQ0060QJRJVQWMHHE', NULL, 'https://github.com/Hypercart-Dev-Tools/rebalance-OS/issues/266', '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GENN684JS0F3CFE7X', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.73.0', 'Subsystem Unification', 'shipped', '2026-12-15', '2026-08-17', 'Foundational test isolation and DRY infrastructure consolidation across collectors and libraries. #7 HiQS test process isolation, #25 time_ops timestamp consolidation, #26 GitHubClient routing, #27 database persistence/upsert deduplication, #28 git_ops subprocess wrapper, #30 dead code and stale doc cleanup. Shipped ahead of 0.70.0-0.72.0, which remain unshipped drafts.', NULL, 'ref-01M0V6SS5G6P2M7AHBFA9G449Q', NULL, NULL, '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GPB9K6ASGKZZDHETD', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.74.0', 'Hardened Core', 'draft', '2027-01-15', NULL, 'Security invariant hardening, core parser test coverage, and repo hygiene enforcement. #31 close coverage gaps (md_parser, note_ingester, slack_users, MCP tools), #32 pre-embed secret redaction regression tests and chunk purge/re-index, #33 transcript suppression and clean repo hygiene.', NULL, 'ref-01M0V6SS5GV2PJ9E80HM8HR5G8', NULL, NULL, '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0V6SS5GG4HY5PE63HAEXYA0', 'repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0.75.0', 'Fleet Engine', 'draft', '2027-02-15', NULL, 'Unified fleet collection, streamlined scheduler topology, shared presentation layer, and multi-signal auto-promotion. #29 shared SQL read layer and web app mount, #23 pulse/fleet collector stack consolidation, #22 Mac Studio scheduler jobs reload, #4 Mac Studio pulse collector conflict recovery, #1 sustained-activity auto-promotion engine, #74 consolidate the dual end-of-day LLM vault synthesis jobs into one pipeline.', NULL, 'ref-01M0V6SS5GE1T1PHVMBG0J1021', NULL, NULL, '', NULL, NULL, 'Yes', NULL, NULL, NULL);
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid) VALUES('mfi-01M0V940ASQHCQHZF33GVS34V8', 'rel-01M0V6SS5FEQMK5FVTZHR7KPRR', 'ref-01M0V940AVPRE48N0S5H08EKTV', 'dialed_in', '2026-08-25T01:38:53Z', 'Focus 5 horizontal layout mode plus the CLIO silent-write fix; both surface-level items that fit the Green Board goal of one honest status surface.', NULL);
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '0', '# Major Releases');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '1', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '2', 'Forward-looking planning ledger for major releases — one block per release, minimal fields, blank');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '3', 'line between blocks. Marathon plans and other forward planning cross-reference this doc for');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '4', 'target release names/dates; it is not a history of what shipped (that''s CHANGELOG.md — lessons');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '5', 'learned belong there at ship time, not duplicated here). Contract lives in PROJECT/PDDA.md ->');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '6', '"RELEASES.md — release ledger". Add new fields only when a real need shows up.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '7', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '8', '`Description:` opens with **one sentence of plain prose** naming the arc, then the manifest of GH');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '9', 'issues the release closes. The prose is not decoration: under the public repo''s fresh single-commit');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '10', 'history there is no issue tracker to resolve the numbers against, so a bare manifest reads as');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '11', 'pointers to nothing. `Exit:` is the one observable that decides whether it shipped. Both stay on a');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '12', 'single line. Issue state verified 2026-08-18 against HiQS-Suite/rebalanceOS, the live repo (#55 retires the old one).');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '13', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '14', '> **`#nnn` and `GH-nnn` refer to this project''s internal issue tracker.** They are retained as');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '15', '> historical labels, not links — in the public repository they do not resolve to anything, and that');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '16', '> is expected. The prose in each `Description:` carries the meaning on its own.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0V6SMAYVR4WS5ASTP68TEE5', '17', '');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5FS9F0H2EKDTHEPKDE', '19', 'Iterations: 0.69.0-0.69.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5FS9F0H2EKDTHEPKDE', '25', 'Exit: MET 2026-08-14 — doctor reports OK on both orphan-vector invariants (0 github, 0 semantic); store 14.62 GB -> 3.81 GB, live vectors 32,908 unchanged. R1 waived by the operator for wall clock, recorded in the runbook. #250 stays open pending issue closure (api.github.com was unreachable).');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5FEQMK5FVTZHR7KPRR', '32', 'Iterations: 0.70.0-0.70.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5FEQMK5FVTZHR7KPRR', '38', 'Exit: A clean clone on a machine that has never run rebalance completes the documented README Getting Started path end to end — install, onboarding, first pulse — with no undocumented step, and `rebalance doctor` then reports no FAIL. Verified on one Apple Silicon host — macOS-first launch by operator decision 2026-08-15; Linux/Windows are documented as work in progress rather than gated, after a Docker pre-flight showed stock Ubuntu images ship no `python3` at all and 22.04 cannot reach the 3.12 floor from its own archive. `/front-door`, `/shakedown` and a full-history TruffleHog scan are gates tracked in #66, evidence retained.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GPFMAANZG4GYFAV4X', '45', 'Iterations: 0.71.0-0.71.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GPFMAANZG4GYFAV4X', '51', 'Exit: net LOC <= -2,000 measured; zero local generation models in the ask path; renderers <= 2; launchd jobs <= 9; search surfaces = 2; tests/test_surface_budgets.py green and pinning the post-subtraction counts.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GE588Z6MNRK6X4Y6H', '58', 'Iterations: 0.72.0-0.72.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GE588Z6MNRK6X4Y6H', '64', 'Exit: one 7-day daily-driver window on the 64 GB Mac Studio — MLX allocation under the #217 cap (0.35 x RAM, ~22 GB) read from #216 instrumentation; no rebalance process over 32 GB phys_footprint; zero `database is locked`; doctor OK daily. In-scope defects reset the clock, environmental flakes do not. Defects the window finds are fixed here, scope frozen the day it closes; anything later goes to ROADMAP.md.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GENN684JS0F3CFE7X', '71', 'Iterations: 0.73.0-0.73.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GENN684JS0F3CFE7X', '77', 'Exit: PARTIALLY MET 2026-08-17 — the two suites run as separate processes with no leakage, no timestamp alias wrappers or private git runners remain in the modules each phase named, and a contract test now pins GitHub auth headers to the shared client. Not met: two collectors still shell out to git directly (coverage probing and commit backfill, the latter keeping a fifth private runner), the contract test that would have caught them was never written, and timestamp bypass sites remain outside the modules the phase scoped. Carried forward on #25 and #28.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GPB9K6ASGKZZDHETD', '84', 'Iterations: 0.74.0-0.74.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GPB9K6ASGKZZDHETD', '90', 'Exit: Secret redaction regression suite green with zero key leaks in semantic queries; md_parser and note_ingester direct unit tests pass; relay-system/ transcripts strictly uncommitted.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GG4HY5PE63HAEXYA0', '97', 'Iterations: 0.75.0-0.75.9');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V6SS5GG4HY5PE63HAEXYA0', '103', 'Exit: Pulse collection consolidated into 3 supervised launchd jobs; Mac Studio device heartbeat fresh (<1h) with zero doctor alerts; multi-signal 5-action auto-promotion operational with 20h burst guard; the 18:20/18:30 obsidian-daily-sync + git-pulse-daily-synthesis pair replaced by one launchd job that runs both syntheses in-process, so block order no longer depends on launchd scheduling.');
